        let child = path.child(b"-space \n\xff").unwrap();
        assert_eq!(child.bytes(), b"/a/b/-space \n\xff");
        assert_eq!(child.parent().unwrap().unwrap().bytes(), b"/a/b");
        assert_eq!(path.parent().unwrap().unwrap().bytes(), b"/a");
