        let pool = Budget::new(8 * 1024 * 1024, 0);
        let root = RemotePath::new(&pool, b"/").unwrap();
        let bytes = names(&[
            (b"z-dir", Some(0o040755)),
            (b"a\nb", Some(0o100644)),
            (b"link", Some(0o120777)),
            (b".hidden", None),
            (b".", None),
            (b"..", None),
            (b"../escape", None),
