//! 顺序目录操作；错误使独立通道失效，监督器必须关闭底层连接。
use super::{
    client::{Channel, Error as ChannelError},
    model::{self, Listing, RemotePath, Scan},
    wire::{Expected, HandleOp, PathOp, Request, Response},
};
use crate::tasks::Cancellation;
use std::io::{Read, Write};

#[derive(Debug)]
pub enum Error {
    Channel(ChannelError),
    Model(model::Error),
    Remote(u32),
    Unexpected,
    Local(std::io::Error),
    Changed,
}
impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Channel(ChannelError::Io(error)) => write!(f, "SFTP IO 错误：{}", error.kind()),
            Self::Channel(error) => write!(f, "SFTP 通道错误：{error:?}"),
            Self::Model(error) => write!(f, "SFTP 目录错误：{error:?}"),
            Self::Remote(code) => write!(f, "SFTP 远端状态码：{code}"),
            Self::Unexpected => f.write_str("SFTP 响应类型错误"),
            Self::Local(error) => write!(f, "SFTP 本地 IO 错误：{}", error.kind()),
            Self::Changed => f.write_str("SFTP 文件长度变化或未读足，未提交完成"),
        }
    }
}
impl std::error::Error for Error {}
impl From<ChannelError> for Error {
    fn from(error: ChannelError) -> Self {
        Self::Channel(error)
    }
}
impl From<std::io::Error> for Error {
    fn from(error: std::io::Error) -> Self {
        Self::Local(error)
    }
}
impl From<model::Error> for Error {
    fn from(error: model::Error) -> Self {
        Self::Model(error)
    }
}
impl From<super::wire::Error> for Error {
    fn from(error: super::wire::Error) -> Self {
        Self::Channel(ChannelError::Wire(error))
    }
}
pub(super) fn remote(response: Response<'_>) -> Error {
    match response {
        Response::Status { code, .. } => Error::Remote(code),
        _ => Error::Unexpected,
    }
}
pub fn directory<I: Read + Write>(
    channel: &mut Channel<I>,
    path: RemotePath,
    hidden: bool,
    cancel: &Cancellation,
) -> Result<Listing, Error> {
    let result = (|| {
        // 大目录工作集先准入，不能拿到远端句柄后再因本地额度不足退出。
        let source = channel.source();
        let mut scan = Scan::new(source.session, source.generation, path.clone(), hidden)?;
        channel.issue(Expected::Handle, |id| Request::Path { id, op: PathOp::OpenDir, path: path.bytes() }, cancel)?;
        let opened = channel.receive(cancel)?;
        let response = opened.response()?;
        let Response::Handle { handle, .. } = response else {
            return Err(remote(response));
        };
        let eof = loop {
            channel.issue(Expected::Names, |id| Request::Handle { id, op: HandleOp::ReadDir, handle }, cancel)?;
            let page = channel.receive(cancel)?;
            match page.response()? {
                Response::Names { names, .. } => {
                    if scan.push(&names, cancel)? {
                        break false;
                    }
                }
                Response::Status { code: 1, .. } => break true,
                other => return Err(remote(other)),
            }
        };
        channel.issue(Expected::Status, |id| Request::Handle { id, op: HandleOp::Close, handle }, cancel)?;
        match channel.receive(cancel)?.response()? {
            Response::Status { code: 0, .. } => {}
            other => return Err(remote(other)),
        }
        scan.finish(eof).map_err(Error::from)
    })();
    if result.is_err() {
        channel.abort();
    }
    result
}

//! 单文件流式原语；目标选择、任务队列和本地原子提交由调用者负责。
use super::{
    client::{Channel, Error as ChannelError},
    operations::{Error, remote},
    wire::{Attributes, CHUNK_LIMIT, Expected, HandleOp, Request, Response},
};
use crate::tasks::Cancellation;
use std::io::{Read, Write};

fn check(cancel: &Cancellation) -> Result<(), Error> {
    if cancel.is_cancelled() { Err(ChannelError::Cancelled.into()) } else { Ok(()) }
}
fn status<I: Read + Write>(channel: &mut Channel<I>, cancel: &Cancellation) -> Result<(), Error> {
    match channel.receive(cancel)?.response()? {
        Response::Status { code: 0, .. } => Ok(()),
        other => Err(remote(other)),
    }
}
fn size<I: Read + Write>(
    channel: &mut Channel<I>,
    handle: &[u8],
    length: u64,
    cancel: &Cancellation,
) -> Result<(), Error> {
    channel.issue(Expected::Attrs, |id| Request::Handle { id, op: HandleOp::Fstat, handle }, cancel)?;
    match channel.receive(cancel)?.response()? {
        Response::Attrs { attrs, .. } if attrs.size == Some(length) => Ok(()),
        Response::Attrs { .. } => Err(Error::Changed),
        other => Err(remote(other)),
    }
}
fn close<I: Read + Write>(channel: &mut Channel<I>, handle: &[u8], cancel: &Cancellation) -> Result<(), Error> {
    channel.issue(Expected::Status, |id| Request::Handle { id, op: HandleOp::Close, handle }, cancel)?;
    status(channel, cancel)
}
pub struct Upload<'a> {
    pub temporary: &'a [u8],
    pub destination: &'a [u8],
    pub length: u64,
    pub replace: bool,
}
/// 临时名由上层唯一生成并展示；排他创建、逐块 ACK、大小复核、关闭 ACK 后才重命名。
/// 出错保留临时文件供用户识别，不自动删除；重试必须使用新临时名。
pub fn upload<I: Read + Write, R: Read>(
    channel: &mut Channel<I>,
    input: &mut R,
    target: Upload<'_>,
    cancel: &Cancellation,
    mut progress: impl FnMut(u64),
) -> Result<u64, Error> {
    let result = (|| {
        check(cancel)?;
        if target.temporary == target.destination {
            return Err(Error::Unexpected);
        }
        if target.replace && !channel.capabilities().posix_rename {
            return Err(super::wire::Error::UnsupportedExtension.into());
        }
        let _memory = channel.reserve(CHUNK_LIMIT)?;
        let mut buffer = [0u8; CHUNK_LIMIT];
        channel.issue(
            Expected::Handle,
            |id| Request::Open {
                id,
                path: target.temporary,
                flags: 2 | 8 | 32,
                attrs: Attributes { permissions: Some(0o600), ..Attributes::default() },
            },
            cancel,
        )?;
        let opened = channel.receive(cancel)?;
        let response = opened.response()?;
        let Response::Handle { handle, .. } = response else {
            return Err(remote(response));
        };
        let mut offset = 0;
        while offset < target.length {
            check(cancel)?;
            let length = (target.length - offset).min(CHUNK_LIMIT as u64) as usize;
            let count = match input.read(&mut buffer[..length]) {
                Err(error) if error.kind() == std::io::ErrorKind::Interrupted => continue,
                other => other?,
            };
            if count == 0 {
                return Err(Error::Changed);
            }
            channel.issue(
                Expected::Status,
                |id| Request::Write { id, handle, offset, data: &buffer[..count] },
                cancel,
            )?;
            status(channel, cancel)?;
            offset += count as u64;
            progress(offset);
        }
        loop {
            check(cancel)?;
            match input.read(&mut buffer[..1]) {
                Ok(0) => break,
                Ok(_) => return Err(Error::Changed),
                Err(error) if error.kind() == std::io::ErrorKind::Interrupted => {}
                Err(error) => return Err(error.into()),
            }
        }
        size(channel, handle, target.length, cancel)?;
        if channel.capabilities().fsync {
            channel.issue(Expected::Status, |id| Request::Fsync { id, handle }, cancel)?;
            status(channel, cancel)?;
        }
        close(channel, handle, cancel)?;
        drop(opened);
        channel.issue(
            Expected::Status,
            |id| Request::Rename { id, old: target.temporary, new: target.destination, replace: target.replace },
            cancel,
        )?;
        status(channel, cancel)?;
        Ok(offset)
    })();
    if result.is_err() {
        channel.abort();
    }
    result
}
/// 输出只写调用者提供的暂存目标；成功也不替调用者重命名或宣告磁盘持久化。
pub fn download<I: Read + Write, W: Write>(
    channel: &mut Channel<I>,
    path: &[u8],
    output: &mut W,
    length: u64,
    cancel: &Cancellation,
    mut progress: impl FnMut(u64),
) -> Result<u64, Error> {
    let result = (|| {
        check(cancel)?;
        channel.issue(
            Expected::Handle,
            |id| Request::Open { id, path, flags: 1, attrs: Attributes::default() },
            cancel,
        )?;
        let opened = channel.receive(cancel)?;
        let response = opened.response()?;
        let Response::Handle { handle, .. } = response else {
            return Err(remote(response));
        };
        size(channel, handle, length, cancel)?;
        let mut offset = 0;
        loop {
            let maximum = (length - offset).clamp(1, CHUNK_LIMIT as u64) as usize;
            channel.issue(
                Expected::Data(maximum),
                |id| Request::Read { id, handle, offset, length: maximum as u32 },
                cancel,
            )?;
            let page = channel.receive(cancel)?;
            match page.response()? {
                Response::Status { code: 1, .. } if offset == length => break,
                Response::Status { code: 1, .. } => return Err(Error::Changed),
                Response::Data { data, .. } => {
                    if data.len() as u64 > length - offset {
                        return Err(Error::Changed);
                    }
                    let mut rest = data;
                    while !rest.is_empty() {
                        check(cancel)?;
                        match output.write(rest) {
                            Ok(0) => return Err(std::io::Error::from(std::io::ErrorKind::WriteZero).into()),
                            Ok(n) => rest = &rest[n..],
                            Err(error) if error.kind() == std::io::ErrorKind::Interrupted => {}
                            Err(error) => return Err(error.into()),
                        }
                    }
                    offset += data.len() as u64;
                    progress(offset);
                }
                other => return Err(remote(other)),
            }
        }
        size(channel, handle, length, cancel)?;
        close(channel, handle, cancel)?;
        check(cancel)?;
        output.flush()?;
        Ok(offset)
    })();
    if result.is_err() {
        channel.abort();
    }
    result
}

